-- 0017_firmware_issues — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- D-31 (Vlad, 14 Nov): each device carries its firmware (0007) and algorithm version, entered by hand now and
-- later from the device platform API; known problems of a firmware are recorded once, so every project with
-- that firmware shows them.
ALTER TABLE device ADD COLUMN algorithm_version text CHECK (algorithm_version <> '');

-- firmware_issue: internal reference data kept by R&D, not client data — no client_id; staff only, never
-- shown to clients or partners. A known problem of one firmware version of one model.
CREATE TABLE firmware_issue (
  id          uuid PRIMARY KEY,
  model       text NOT NULL CHECK (btrim(model) <> ''),
  firmware    text NOT NULL CHECK (btrim(firmware) <> ''),
  summary     text NOT NULL CHECK (btrim(summary) <> ''),
  severity    text NOT NULL CHECK (severity IN ('info', 'degraded', 'critical')),
  -- Where the problem is documented (release note, case, ticket); no secrets, no client data.
  source      text,
  created_by  uuid NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz
);
CREATE INDEX firmware_issue_active ON firmware_issue (upper(model), firmware) WHERE archived_at IS NULL;

ALTER TABLE firmware_issue ENABLE ROW LEVEL SECURITY;
CREATE POLICY firmware_issue_internal ON firmware_issue FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON firmware_issue TO ocs_app;
